 3	import java.util.ArrayDeque;
 4	import java.util.ArrayList;
 5	import java.util.Deque;
 6	import java.util.List;
 7	
 8	public class DepthFirstSearch {
 9	
10	    private DepthFirstSearch() {
11	    }
12	
13	    public static List<Integer> dfs(List<List<Integer>> adjacencyList) {
14	        validateAdjacencyList(adjacencyList);
15	
16	        boolean[] visitedVertices = new boolean[adjacencyList.size()];
17	        List<Integer> traversalOrder = new ArrayList<>();
18	
19	        for (int vertex = 0; vertex < adjacencyList.size(); vertex++) {
20	            if (!visitedVertices[vertex]) {
21	                traverseComponent(adjacencyList, visitedVertices, vertex, traversalOrder);
22	            }
23	        }
24	
25	        return traversalOrder;
26	    }
27	
28	    private static void validateAdjacencyList(List<List<Integer>> adjacencyList) {
29	        if (adjacencyList == null) {
30	            throw new IllegalArgumentException("adjacencyList must not be null");
31	        }
32	
33	        int vertexCount = adjacencyList.size();
34	        for (int vertex = 0; vertex < vertexCount; vertex++) {
35	            List<Integer> neighbors = adjacencyList.get(vertex);
36	            if (neighbors == null) {
37	                throw new IllegalArgumentException("Neighbors for vertex " + vertex + " must not be null");
38	            }
39	
40	            for (Integer neighbor : neighbors) {
41	                if (neighbor == null) {
42	                    throw new IllegalArgumentException("Neighbor for vertex " + vertex + " must not be null");
43	                }
44	                if (neighbor < 0 || neighbor >= vertexCount) {
45	                    throw new IllegalArgumentException(
46	                            "Neighbor " + neighbor + " for vertex " + vertex + " is outside the graph");
47	                }
48	            }
49	        }
50	    }
51	
52	    private static void traverseComponent(
53	            List<List<Integer>> adjacencyList,
54	            boolean[] visitedVertices,
55	            int startVertex,
56	            List<Integer> traversalOrder) {
57	        Deque<Integer> pendingVertices = new ArrayDeque<>();
58	        pendingVertices.push(startVertex);
59	
60	        while (!pendingVertices.isEmpty()) {
61	            int vertex = pendingVertices.pop();
62	            if (visitedVertices[vertex]) {
63	                continue;
64	            }
65	
66	            visitedVertices[vertex] = true;
67	            traversalOrder.add(vertex);
68	
69	            List<Integer> neighbors = adjacencyList.get(vertex);
70	            for (int index = neighbors.size() - 1; index >= 0; index--) {
71	                int neighbor = neighbors.get(index);
72	                if (!visitedVertices[neighbor]) {
73	                    pendingVertices.push(neighbor);
74	                }
75	            }
76	        }
77	    }
