19	    private static List<List<Integer>> buildSampleGraph() {
20	        List<List<Integer>> adjacencyList = createGraph(VERTEX_COUNT);
21	
22	        for (int[] edge : SAMPLE_EDGES) {
23	            addUndirectedEdge(adjacencyList, edge[0], edge[1]);
24	        }
25	
26	        return adjacencyList;
27	    }
